package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class WrittenSingleProductsTest {
 @Test public void all9900PublicProductsHaveBlankFormalLayoutAndCorrectCarryChecks(){Set<String> signatures=new HashSet<>();int tested=0;for(String id:List.of("mul2","mul3"))for(int i=0;i<WrittenSingleProducts.count(id);i++){Question q=WrittenSingleProducts.indexed(id,i);int[] v=WrittenSingleProducts.read(q);assertNotNull(v);assertTrue(signatures.add(q.signature()));q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(""+(v[0]*v[1]))).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(v[0]*v[1]+1))).status);VerticalWork.Layout layout=VerticalWork.layout(q);assertNotNull(layout);assertEquals("*",layout.operator);assertEquals(""+v[0],layout.top);assertEquals(""+v[1],layout.bottom);VerticalWork.Draft draft=new VerticalWork.Draft();assertTrue(draft.cells.isEmpty());assertNull(VerticalWork.answer(q,draft));int digits=id.equals("mul2")?2:3,carry=0;for(int p=0;p<digits;p++){int value=v[0]/(int)Math.pow(10,p)%10*v[1]+carry;draft.cells.put("answer:"+p,""+(value%10));carry=value/10;draft.cells.put("mulCarry0:"+(p+1),""+carry);}if(carry>0)draft.cells.put("answer:"+digits,""+carry);assertFalse(VerticalWork.check(q,draft).error());assertEquals(v[2],Integer.parseInt(VerticalWork.answer(q,draft)));Map<String,String> before=new HashMap<>(draft.cells);int old=Integer.parseInt(draft.cells.get("answer:0"));draft.cells.put("answer:0",""+((old+1)%10));assertEquals(Set.of("answer:0"),VerticalWork.check(q,draft).wrong);assertEquals(""+((old+1)%10),draft.cells.get("answer:0"));draft.cells.put("answer:0",before.get("answer:0"));HelpPlan help=HelpPlan.forQuestion(q);assertFalse(help.canTransfer());assertTrue(help.restore(null,q.id).entries.stream().allMatch(String::isEmpty));tested++;}assertEquals(9900,tested);}
 @Test public void normalGeneratorSupplyUsesZeroAndAllFactorsWithoutRepeating(){Generator gen=new Generator(new Random(148));for(String id:List.of("mul2","mul3")){CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",id,4);assertTrue(WrittenSingleProducts.selected(id,limits));List<String> history=new ArrayList<>();Set<Integer> factors=new HashSet<>();for(int i=0;i<300;i++){Question q=gen.next(id,history,false,limits);assertEquals(WrittenSingleProducts.KIND,q.kind);assertFalse(history.contains(q.signature()));history.add(q.signature());factors.add(WrittenSingleProducts.read(q)[1]);}assertEquals(10,factors.size());Map<String,Integer> full=new LinkedHashMap<>();for(int i=0;i<WrittenSingleProducts.count(id);i++)full.put(WrittenSingleProducts.indexed(id,i).signature(),i);assertEquals(WrittenSingleProducts.indexed(id,0).signature(),WrittenSingleProducts.next(id,new Random(1),limits,full).signature());}assertFalse(WrittenSingleProducts.selected("mul2",GlobalCurriculum.limits("england-primary-2021-v1","mul2",3)));Learning.Profile profile=new Learning.Profile();GlobalCurriculum.chooseCountry(profile,"GB");GlobalCurriculum.choosePack(profile,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(profile).inGrade("mul2",4));assertTrue(GlobalCurriculum.pack(profile).inGrade("mul2",3));}
 @Test public void corruptPublicPromptsDoNotBecomeTrustedAnswerKeys(){Question q=WrittenSingleProducts.indexed("mul3",8999);assertArrayEquals(new int[]{999,9,8991},WrittenSingleProducts.read(q));q.prompt="999 × 99";assertNull(WrittenSingleProducts.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("8991")).status);q=WrittenSingleProducts.indexed("mul2",0);assertEquals(0,WrittenSingleProducts.read(q)[2]);assertTrue(new Checker().check(q,List.of(),List.of("0")).correct());}
}
